-- =====================================================================
-- dbinsert.sql : 샘플 데이터 초기화 스크립트
-- 작성자: 정서진 (2. 데이터)  /  district·calendar 부분 작성자: 김수연
-- 실행 순서: dbcreate.sql → dbinsert.sql
-- 넣는 순서: district → calendar → station → weather → rental_daily
-- (user_account, fault_report 는 담당자 확정 후 추가 예정)
-- =====================================================================
SET NAMES utf8mb4;

-- =====================================================================
-- district_seed.sql : 자치구 9개 (실제 공공데이터 기반)
-- 작성자 : 김수연 (1. DB 설계) → 2번(정서진) dbinsert.sql 맨 앞에 합치기
--
-- 출처
--   district_id   : 행정표준 시군구 코드 (행정안전부 법정동코드 앞 5자리)
--   life_zone     : 서울시 2030 서울생활권계획 5대 권역생활권
--   daytime_index : 통계청 2020 인구주택총조사
--                   「성별/연령별 상주(야간)·주간 인구 - 시군구」
--                   주간인구지수 = (상주 + 유입 - 유출) / 상주 × 100
--                   소수점 첫째 자리에서 반올림한 정수로 저장
--   ※ district_type 은 생성 컬럼이라 INSERT 하지 않음
-- =====================================================================


INSERT INTO district (district_id, district_name, life_zone, daytime_index) VALUES
